function lop_csv_row($stream,array $fields): void {foreach($fields as &$field)if(is_string($field)&&preg_match('/^[\s]*[=+@-]/u',$field))$field="'".$field;unset($field);fputcsv($stream,$fields);}
try{lop_require($koneksi);$b=$batch!==''?lf_one($koneksi,"SELECT * FROM legacy_full_batches WHERE id=? AND state='completed'",[$batch]):['unit_id'=>unit_active_id()];if(!$b)throw new DomainException('Batch belum terverifikasi atau tidak ditemukan.',404);
    if($classId){$directoryClass=class_find($koneksi,(int)$classId);if(!$directoryClass)throw new DomainException('Kelas tidak ditemukan pada unit ini.',404);$context['class_id']=$classId;}
    if($groupId){$group=lf_one($koneksi,"SELECT g.* FROM legacy_op_groups g WHERE g.id=? AND EXISTS(SELECT 1 FROM legacy_op_owners o WHERE o.group_id=g.id AND o.unit_id=g.unit_id AND (?='' OR o.batch_id=?))",[$groupId,$batch,$batch]);if(!$group)throw new DomainException('Kelompok tidak ditemukan pada hasil migrasi ini.',404);}
    $like='%'.$search.'%';$directoryWhere="EXISTS(SELECT 1 FROM legacy_full_batches cb WHERE cb.id=o.batch_id AND cb.unit_id=o.unit_id AND cb.state='completed') AND (?='' OR o.batch_id=?) AND (o.name LIKE ? OR o.source_identity LIKE ?)";$directoryArgs=[$batch,$batch,$like,$like];
    if($classId){$directoryWhere.=' AND EXISTS(SELECT 1 FROM legacy_op_groups cg WHERE cg.id=o.group_id AND cg.unit_id=o.unit_id AND cg.master_kelas_id=?)';$directoryArgs[]=$classId;}
    if($group){$directoryWhere.=' AND o.group_id=?';$directoryArgs[]=$groupId;}
    $total=(int)lf_one($koneksi,'SELECT COUNT(*) n FROM legacy_op_owners o WHERE '.$directoryWhere,$directoryArgs)['n'];$page=min($page,max(1,(int)ceil($total/25)));
    $context=array_replace($context,['q'=>$search,'page'=>$page]);if($group)$context['group']=$groupId;
    $rows=lf_rows($koneksi,'SELECT o.*,g.label group_label,g.master_kelas_id group_class_id,a.balance,a.opening FROM legacy_op_owners o LEFT JOIN legacy_op_groups g ON g.id=o.group_id AND g.unit_id=o.unit_id LEFT JOIN legacy_op_accounts a ON a.owner_id=o.id AND a.unit_id=o.unit_id WHERE '.$directoryWhere.' ORDER BY o.name,o.id LIMIT 25 OFFSET '.(($page-1)*25),$directoryArgs);
    foreach($rows as &$row)if($row['group_class_id']&&($currentClass=class_find($koneksi,(int)$row['group_class_id'])))$row['group_label']=class_label($currentClass);unset($row);
    if($group)$group['label']=legacy_class_label($koneksi,$group);
    if($ownerId)$selected=lf_one($koneksi,"SELECT o.* FROM legacy_op_owners o WHERE o.id=? AND (?='' OR o.batch_id=?) AND (?=0 OR o.group_id=?) AND (?=0 OR EXISTS(SELECT 1 FROM legacy_op_groups cg WHERE cg.id=o.group_id AND cg.unit_id=o.unit_id AND cg.master_kelas_id=?)) AND EXISTS(SELECT 1 FROM legacy_full_batches cb WHERE cb.id=o.batch_id AND cb.unit_id=o.unit_id AND cb.state='completed')",[$ownerId,$batch,$batch,$groupId?:0,$groupId?:0,$classId?:0,$classId?:0]);
    if($ownerId&&!$selected)throw new DomainException('Pemilik tidak ditemukan pada pilihan kelas/kelompok ini.',404);
    if($_SERVER['REQUEST_METHOD']==='POST'){if(!is_string($_POST['csrf_token']??null)||!hash_equals($_SESSION['csrf_legacy_bank'],$_POST['csrf_token']))throw new DomainException('Token CSRF tidak valid.',403);lop_bank_new($koneksi,(int)$_SESSION['admin_id'],unit_active_id(),(int)$ownerId,$_POST,(string)($_POST['request_key']??''));$notice='Transaksi tersimpan.';}
    if($selected){$account=lf_one($koneksi,'SELECT * FROM legacy_op_accounts WHERE owner_id=?',[$ownerId]);$journals=lf_rows($koneksi,"SELECT * FROM legacy_op_journals WHERE owner_id=? ORDER BY source_date,(origin='adjustment'),id",[$ownerId]);$payments=lf_rows($koneksi,'SELECT * FROM legacy_op_payments WHERE owner_id=? ORDER BY source_date,id',[$ownerId]);}
    if(($_GET['export']??'')==='csv'&&$selected){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="rekening-legacy.csv"');$out=fopen('php://output','w');lop_csv_row($out,['Nama','Identitas sumber','Jenis','Tanggal','Masuk','Keluar','Total pembayaran','Status']);foreach($journals as $j)lop_csv_row($out,[$selected['name'],$selected['source_identity'],'Tabungan',$j['source_date'],$j['incoming'],$j['outgoing'],'',$j['cancelled']?'Dibatalkan':$j['origin']]);foreach($payments as $p)lop_csv_row($out,[$selected['name'],$selected['source_identity'],'Pembayaran',$p['source_date']??'Tanggal tidak tercatat','','',$p['total'],$p['cancelled']?'Dibatalkan':'Legacy']);exit;}
}catch(Throwable $e){http_response_code($e instanceof DomainException&&in_array($e->getCode(),[400,403,404],true)?$e->getCode():409);$error=$e instanceof DomainException?$e->getMessage():'Permintaan gagal. Data tetap disimpan.';}
require_once __DIR__.'/includes/migrated_history.php';
